    "উফ": ["আজ খুব গরম।","উফ, হ্যাঁ! একটু পানি দাও।","It's really hot today. / Ugh, yes! Give me some water."],
    "ইশ": ["আমার ফোনটা ভেঙে গেছে।","ইশ! নতুন ফোন?","My phone has broken. / Oh no! Your new phone?"],
    "বাহ": ["আমি তোমার জন্য বিরিয়ানি রান্না করেছি।","বাহ! খুব ভালো লাগছে।","I've cooked biryani for you. / Wow! It looks great."],
    "হায়": ["আমার ব্যাগটা নেই!","হায়! কোথায় রেখেছিলে?","My bag is gone! / Oh no! Where did you put it?"],
    "আহা": ["বাচ্চাটা ঘুমাচ্ছে।","আহা, কী সুন্দর!","The baby is sleeping. / Aww, how lovely!"],
    "ছি": ["রাস্তাটা খুব নোংরা।","ছি! কেউ পরিষ্কার করে না?","The street is very dirty. / Yuck! Doesn't anyone clean it?"],
    "ধুর": ["আজ আবার বৃষ্টি।","ধুর! বাইরে যেতে পারব না।","Rain again today. / Oh, come on! I can't go out."],
    "হুম": ["তুমি কি চা খাবে?","হুম, একটু খাব।","Will you have some tea? / Hmm, a little."],
    "আহ": ["এই নিন, ঠান্ডা পানি।","আহ, ধন্যবাদ!","Here you are, cold water. / Ah, thanks!"],
    "উহ": ["কী হয়েছে?","উহ! আমার হাত কেটে গেছে।","What happened? / Ouch! I've cut my hand."],
    "ওমা": ["আমি কাল বিয়ে করছি।","ওমা, সত্যি?","I'm getting married tomorrow. / Oh my, really?"],
    "সাবাশ": ["আমি পরীক্ষায় প্রথম হয়েছি!","সাবাশ! খুব ভালো।","I came first in the exam! / Well done! Very good."],
    "উহু": ["তুমি কি আর ভাত খাবে?","উহু, আর না।","Will you have more rice? / Nope, no more."],
    "আলহামদুলিল্লাহ": ["কেমন আছেন?","আলহামদুলিল্লাহ, ভালো আছি।","How are you? / Thank God, I'm well."],
    "ইনশাআল্লাহ": ["কাল আসবেন?","ইনশাআল্লাহ, আসব।","Will you come tomorrow? / God willing, I'll come."],
    "মাশাআল্লাহ": ["এটা আমার মেয়ে।","মাশাআল্লাহ, খুব সুন্দর!","This is my daughter. / How wonderful, she's beautiful!"],
    "হায় আল্লাহ": ["রাস্তায় খুব জ্যাম।","হায় আল্লাহ! আমার দেরি হবে।","There's a big traffic jam. / Oh God! I'll be late."],
    "না": ["তুমি কি ক্লান্ত?","না, আমি ক্লান্ত না।","Are you tired? / No, I'm not tired."],
    "তো": ["তো, কাল কী করবে?","কাল বাজারে যাব।","So, what will you do tomorrow? / I'll go to the market tomorrow."]
